	uint64 FFunctionOverrideHandle::GenerateNewId()
	{
		static std::atomic<uint64> NextId = 0;

		/* Zero is reserved for the invalid handle. */
		return NextId.fetch_add(1, std::memory_order_relaxed) + 1;
	}

	/*-----------------------------------------------------------------------------
		FScopedMemoryWriteAccess
	-----------------------------------------------------------------------------*/

	FScopedMemoryWriteAccess::FScopedMemoryWriteAccess(void* InAddress, SIZE_T InSize)
		: Address(InAddress), Size(InSize)
	{
		if (Address == nullptr || Size == 0)
			return;

		DWORD OldProtection = 0;

		if (::VirtualProtect(Address, Size, PAGE_EXECUTE_READWRITE, &OldProtection))
		{
			PreviousProtection = static_cast<uint32>(OldProtection);
			bIsValid = true;
		}
	}

	FScopedMemoryWriteAccess::~FScopedMemoryWriteAccess()
	{
		if (!bIsValid)
			return;

		DWORD Unused = 0;
		::VirtualProtect(Address, Size, static_cast<DWORD>(PreviousProtection), &Unused);

		::FlushInstructionCache(::GetCurrentProcess(), Address, Size);
	}

	/*-----------------------------------------------------------------------------
		FModuleImage
	-----------------------------------------------------------------------------*/

	void* FModuleImage::GetBaseAddress(const wchar_t* ModuleName)
	{
		return reinterpret_cast<void*>(::GetModuleHandleW(ModuleName));
	}

	SIZE_T FModuleImage::GetImageSize(const wchar_t* ModuleName)
	{
		const uint8* const Base = reinterpret_cast<const uint8*>(GetBaseAddress(ModuleName));

		if (Base == nullptr)
			return 0;

		const IMAGE_DOS_HEADER* const DosHeader = reinterpret_cast<const IMAGE_DOS_HEADER*>(Base);

		if (DosHeader->e_magic != IMAGE_DOS_SIGNATURE)
			return 0;

		const IMAGE_NT_HEADERS* const NtHeaders = reinterpret_cast<const IMAGE_NT_HEADERS*>(Base + DosHeader->e_lfanew);

		if (NtHeaders->Signature != IMAGE_NT_SIGNATURE)
			return 0;

		return static_cast<SIZE_T>(NtHeaders->OptionalHeader.SizeOfImage);
	}

	void* FModuleImage::ResolveRelativeAddress(uint64 RelativeVirtualAddress, const wchar_t* ModuleName)
	{
		uint8* const Base = reinterpret_cast<uint8*>(GetBaseAddress(ModuleName));

		if (Base == nullptr)
			return nullptr;

		/* Reject anything past the end of the image; a stale offset is better caught here than followed. */
		const SIZE_T ImageSize = GetImageSize(ModuleName);

		if (ImageSize != 0 && RelativeVirtualAddress >= ImageSize)
			return nullptr;

		return Base + RelativeVirtualAddress;
	}

	uint64 FModuleImage::GetRelativeAddress(const void* Address, const wchar_t* ModuleName)
	{
		const uint8* const Base = reinterpret_cast<const uint8*>(GetBaseAddress(ModuleName));

		if (Base == nullptr || Address == nullptr || reinterpret_cast<const uint8*>(Address) < Base)
			return 0;

		return static_cast<uint64>(reinterpret_cast<const uint8*>(Address) - Base);
	}

